        {
            var response = ReadResponseAsync().GetAwaiter().GetResult();
            _responseReader?.Dispose();
            _responseReader = new BinaryReader(new MemoryStream(response, false), System.Text.Encoding.UTF8, false);
            if (!Response.ReadBoolean()) throw new InvalidOperationException(Response.ReadString());
        }
        catch (Exception error) when (error is IOException or EndOfStreamException or OperationCanceledException or InvalidDataException)
        {
            var timedOut = error is OperationCanceledException;
            var exit = _process is { HasExited: true } ? $"{ProcessCoreConstants.ProcessExitDiagnosticPrefix}{_process.ExitCode}{ProcessCoreConstants.ProcessExitDiagnosticSuffix}" : string.Empty;
            _connectionFailed = true;
            TerminateProcess();
            throw new InvalidOperationException(timedOut ? CommonExceptions.ProcessTimeout() : CommonExceptions.ProcessCommunicationFailed(exit), error);
        }
    }

    private Task<byte[]> ReadResponseAsync() =>
        EmulationHostProtocolFunctions.ReadResponseAsync(_pipe!, TimeSpan.FromSeconds(ProcessCoreConstants.HostResponseTimeoutSeconds),
            CancellationToken.None, length => CommonExceptions.InvalidResponseLength(length));

    private void TerminateProcess()
    {
        DisposeSafely(_pipe);
        _pipe = null;
        var process = _process;
        _process = null;
        if (process is null) return;
        try
        {
            EmulationChildProcessLifetime.WaitForExit(process, graceful: false, ProcessCoreConstants.HostExitTimeoutMilliseconds);
        }
        catch (Exception) { }
        finally { DisposeSafely(process); }
    }

    private static void DisposeSafely(IDisposable? value)
    {
        try { value?.Dispose(); }
        catch (Exception) { }
    }

    private BinaryReader Response => _responseReader ?? throw new InvalidOperationException(CommonExceptions.HostResponseUnavailable());

}

