using System.IO;
using System.IO.Pipes;
using Microsoft.Win32.SafeHandles;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

public sealed class TemporaryHostConnectionWaitTests
{
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ConnectedPipeAndParentTokenRemainBorrowed(bool linked)
    {
        NamedPipeServerStream? server = null;
        NamedPipeClientStream? client = null;
        SafePipeHandle? serverHandle = null;
        SafePipeHandle? clientHandle = null;
        Task? connecting = null;
        var lifetime = new CancellationTokenSource();
        var parent = new CancellationTokenSource();
        try
        {
            var name = "gwgui-audit-" + Guid.NewGuid().ToString("N");
            server = CreateServer(name);
            serverHandle = server.SafePipeHandle;
            client = new NamedPipeClientStream(".", name, PipeDirection.InOut, PipeOptions.Asynchronous);
            connecting = client.ConnectAsync(5000, lifetime.Token);
            if (linked)
                EmulationHostProtocolFunctions.WaitForConnection(server, TimeSpan.FromSeconds(5), parent.Token);
            else
                EmulationHostProtocolFunctions.WaitForConnection(server, TimeSpan.FromSeconds(5));
            await connecting;
            clientHandle = client.SafePipeHandle;
            parent.Cancel();
            Assert.True(parent.Token.IsCancellationRequested);
            Assert.True(server.IsConnected);
            Assert.False(serverHandle.IsClosed);
            Assert.False(clientHandle.IsClosed);
            lifetime.CancelAfter(TimeSpan.FromSeconds(5));
            var received = new byte[1];
            var reading = client.ReadExactlyAsync(received, lifetime.Token).AsTask();
            var writing = server.WriteAsync(new byte[] { 0x42 }, lifetime.Token).AsTask();
            await Task.WhenAll(reading, writing);
            Assert.Equal((byte)0x42, received[0]);
        }
        finally
        {
            try { lifetime.Cancel(); }
            finally
            {
                try
                {
                    try { client?.Dispose(); }
                    finally { server?.Dispose(); }
                }
                finally
                {
                    try
                    {
                        if (connecting is not null)
                        {
                            try { await connecting; }
                            catch (OperationCanceledException) when (lifetime.IsCancellationRequested) { }
                            catch (IOException) when (lifetime.IsCancellationRequested) { }
                            catch (ObjectDisposedException) when (lifetime.IsCancellationRequested) { }
                        }
                    }
                    finally
                    {
                        try { parent.Dispose(); }
                        finally { lifetime.Dispose(); }
                    }
                }
            }
        }
        Assert.True(serverHandle!.IsClosed);
        Assert.True(clientHandle!.IsClosed);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void ConnectionDeadlineDoesNotDisposeTheBorrowedServer(bool linked)
    {
        NamedPipeServerStream? server = null;
        SafePipeHandle? handle = null;
        var parent = new CancellationTokenSource();
        try
        {
            server = CreateServer("gwgui-audit-" + Guid.NewGuid().ToString("N"));
            handle = server.SafePipeHandle;
            Assert.ThrowsAny<OperationCanceledException>(() =>
            {
                if (linked)
                    EmulationHostProtocolFunctions.WaitForConnection(server, TimeSpan.FromMilliseconds(20), parent.Token);
                else
                    EmulationHostProtocolFunctions.WaitForConnection(server, TimeSpan.FromMilliseconds(20));
            });
            Assert.False(parent.Token.IsCancellationRequested);
            Assert.False(handle.IsClosed);
        }
        finally
        {
            try { server?.Dispose(); }
            finally { parent.Dispose(); }
        }
        Assert.True(handle!.IsClosed);
    }

    [Fact]
    public void ParentCancellationStopsWaitingWithoutTakingOwnership()
    {
        NamedPipeServerStream? server = null;
        SafePipeHandle? handle = null;
        var parent = new CancellationTokenSource();
        try
        {
            server = CreateServer("gwgui-audit-" + Guid.NewGuid().ToString("N"));
            handle = server.SafePipeHandle;
            parent.Cancel();
            Assert.ThrowsAny<OperationCanceledException>(() =>
                EmulationHostProtocolFunctions.WaitForConnection(server, TimeSpan.FromSeconds(5), parent.Token));
            Assert.True(parent.Token.IsCancellationRequested);
            Assert.False(handle.IsClosed);
        }
        finally
        {
            try { server?.Dispose(); }
            finally { parent.Dispose(); }
        }
        Assert.True(handle!.IsClosed);
    }

    private static NamedPipeServerStream CreateServer(string name) =>
        new(name, PipeDirection.InOut, 1, PipeTransmissionMode.Byte, PipeOptions.Asynchronous);
}

