using System.IO;
using System.Text.Json;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

public sealed class LegacyConfigurationSaveFileAuditTests
{
    [Fact]
    public async Task WritesThePreparedProjectedJsonAndReplacesTheExistingDocument()
    {
        using var fixture = new Fixture();
        using var gate = new SemaphoreSlim(1, 1);
        var prepared = new Document(Guid.NewGuid(), "prepared");
        var options = new JsonSerializerOptions(JsonSerializerDefaults.Web) { WriteIndented = true };
        var calls = new List<string>();
        await ConfigurationFileAccessFunctions.WriteDocumentAtomicallyAsync(gate, fixture.Path,
            new Document(Guid.Empty, "original"),
            value => { calls.Add(value.Value); Assert.Equal(0, gate.CurrentCount); return prepared; },
            value => { calls.Add(value.Value); Assert.Same(prepared, value); return value.Id; },
            value =>
            {
                var directory = System.IO.Path.Combine(fixture.Path, value.Id.ToString("N"));
                var temporary = Assert.Single(Directory.GetFiles(directory));
                Assert.StartsWith("machine.json.", System.IO.Path.GetFileName(temporary));
                Assert.EndsWith(".tmp", temporary);
                Assert.Throws<IOException>(() =>
                {
                    using var probe = File.Open(temporary, FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite);
                });
                calls.Add("projected");
                return value with { Value = "stored" };
            }, options, CancellationToken.None);
        var target = System.IO.Path.Combine(fixture.Path, prepared.Id.ToString("N"), "machine.json");
        var first = JsonSerializer.Deserialize<Document>(await File.ReadAllTextAsync(target), options)!;
        Assert.Equal(prepared.Id, first.Id);
        Assert.Equal("stored", first.Value);
        Assert.Equal(["original", "prepared", "projected"], calls);
        await ConfigurationFileAccessFunctions.WriteDocumentAtomicallyAsync(gate, fixture.Path, prepared,
            static value => value, static value => value.Id, static value => value with { Value = "replacement" },
            options, CancellationToken.None);
        Assert.Equal("replacement", JsonSerializer.Deserialize<Document>(await File.ReadAllTextAsync(target), options)!.Value);
        Assert.Single(Directory.GetFiles(System.IO.Path.GetDirectoryName(target)!));
        Assert.Equal(1, gate.CurrentCount);
    }

    [Fact]
    public async Task ProjectionFailureRemovesTheTemporaryAndReleasesTheGate()
    {
        using var fixture = new Fixture();
        using var gate = new SemaphoreSlim(1, 1);
        var document = new Document(Guid.NewGuid(), "value");
        var failure = new InvalidOperationException("Projection failure");
        var error = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            ConfigurationFileAccessFunctions.WriteDocumentAtomicallyAsync(gate, fixture.Path, document,
                static value => value, static value => value.Id, value =>
                {
                    Assert.Single(Directory.GetFiles(System.IO.Path.Combine(fixture.Path, value.Id.ToString("N"))));
                    throw failure;
                }, new JsonSerializerOptions(), CancellationToken.None));
        Assert.Same(failure, error);
        Assert.Empty(Directory.GetFiles(fixture.Path, "*", SearchOption.AllDirectories));
        Assert.Equal(1, gate.CurrentCount);
    }

    [Fact]
    public async Task ReplacementFailureCleansTheTemporaryAndPreservesTheTargetDirectory()
    {
        using var fixture = new Fixture();
        using var gate = new SemaphoreSlim(1, 1);
        var document = new Document(Guid.NewGuid(), "value");
        var target = System.IO.Path.Combine(fixture.Path, document.Id.ToString("N"), "machine.json");
        Directory.CreateDirectory(target);
        var error = await Record.ExceptionAsync(() =>
            ConfigurationFileAccessFunctions.WriteDocumentAtomicallyAsync(gate, fixture.Path, document,
                static value => value, static value => value.Id, static value => value,
                new JsonSerializerOptions(), CancellationToken.None));
        Assert.True(error is IOException or UnauthorizedAccessException, error?.ToString());
        Assert.True(Directory.Exists(target));
        Assert.Empty(Directory.GetFiles(fixture.Path, "*", SearchOption.AllDirectories));
        Assert.Equal(1, gate.CurrentCount);
    }

    private sealed record Document(Guid Id, string Value);

    private sealed class Fixture : IDisposable
    {
        private static readonly string Workspace = System.IO.Path.GetFullPath(@"F:\GW GUI");
        public string Path { get; } = System.IO.Path.Combine(Workspace, ".save-audit-" + Guid.NewGuid().ToString("N"));

        public Fixture()
        {
            Validate();
            Directory.CreateDirectory(Path);
        }

        public void Dispose()
        {
            Validate();
            if (Directory.Exists(Path)) Directory.Delete(Path, recursive: true);
        }

        private void Validate()
        {
            var full = System.IO.Path.GetFullPath(Path);
            if (!string.Equals(System.IO.Path.GetDirectoryName(full), Workspace, StringComparison.OrdinalIgnoreCase)
                || !System.IO.Path.GetFileName(full).StartsWith(".save-audit-", StringComparison.Ordinal))
                throw new InvalidOperationException("Fixture must stay in the workspace");
        }
    }
}

