using System.IO;
using System.Text.Json;
using System.Text.Json.Serialization;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

public sealed class LegacyConfigurationLoadFileAuditTests
{
    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);

    [Fact]
    public async Task OrdersAcceptedDocumentsAndIgnoresOtherEntries()
    {
        using var fixture = new Fixture();
        fixture.Write("b", Json(new(1, "beta")));
        fixture.Write("A", Json(new(1, "alpha")));
        fixture.Write("broken", "{");
        fixture.Write("null", "null");
        fixture.Write("wrong", Json(new(2, "wrong")));
        Directory.CreateDirectory(System.IO.Path.Combine(fixture.Path, "missing"));
        File.WriteAllText(System.IO.Path.Combine(fixture.Path, "legacy.json"), Json(new(1, "flat")));
        var calls = new List<string>();
        var task = ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Path, "machine.json",
            json => JsonSerializer.Deserialize<Document>(json, Options),
            value => { calls.Add("schema:" + value.Name); return value.SchemaVersion == 1; },
            value => { calls.Add("resolve:" + value.Name); return value with { Name = value.Name.ToUpperInvariant() }; },
            CancellationToken.None);
        Assert.True(task.IsCompletedSuccessfully);
        Assert.Equal(["ALPHA", "BETA"], (await task).Select(value => value.Name));
        Assert.Equal(["schema:alpha", "resolve:alpha", "schema:beta", "resolve:beta", "schema:wrong"], calls);
    }

    [Fact]
    public void CancellationWithAnExistingFileThrowsSynchronouslyBeforeParsing()
    {
        using var fixture = new Fixture();
        fixture.Write("a", Json(new(1, "value")));
        using var stop = new CancellationTokenSource();
        stop.Cancel();
        Assert.Throws<OperationCanceledException>((Action)(() => { _ =
            ConfigurationFileAccessFunctions.ReadDocumentsAsync<Document>(fixture.Path, "machine.json",
                _ => throw new InvalidOperationException("Parser must not run"),
                _ => throw new InvalidOperationException(), _ => throw new InvalidOperationException(), stop.Token); }));
    }

    [Fact]
    public async Task EmptyDirectoryRetainsTheOriginalPrecancelledSuccess()
    {
        using var fixture = new Fixture();
        using var stop = new CancellationTokenSource();
        stop.Cancel();
        var task = ConfigurationFileAccessFunctions.ReadDocumentsAsync<Document>(fixture.Path, "machine.json",
            _ => throw new InvalidOperationException(), _ => throw new InvalidOperationException(),
            _ => throw new InvalidOperationException(), stop.Token);
        Assert.Empty((await task));
    }

    [Theory]
    [InlineData("parse", true)]
    [InlineData("parse", false)]
    [InlineData("schema", true)]
    [InlineData("schema", false)]
    [InlineData("resolve", true)]
    [InlineData("resolve", false)]
    public async Task JsonAndIoErrorsFromEveryStageSkipOnlyTheAffectedFile(string stage, bool jsonError)
    {
        using var fixture = new Fixture();
        fixture.Write("a", Json(new(1, "bad")));
        fixture.Write("b", Json(new(1, "good")));
        void Fail(string current, Document value)
        {
            if (current == stage && value.Name == "bad")
                throw jsonError ? new JsonException("Injected") : new IOException("Injected");
        }
        var task = ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Path, "machine.json",
            json => { var value = JsonSerializer.Deserialize<Document>(json, Options)!; Fail("parse", value); return value; },
            value => { Fail("schema", value); return true; },
            value => { Fail("resolve", value); return value; }, CancellationToken.None);
        Assert.Equal("good", Assert.Single((await task)).Name);
    }

    [Theory]
    [InlineData("parse")]
    [InlineData("schema")]
    [InlineData("resolve")]
    public void OtherErrorsEscapeSynchronously(string stage)
    {
        using var fixture = new Fixture();
        fixture.Write("a", Json(new(1, "bad")));
        var failure = new InvalidOperationException("Injected");
        void Fail(string current)
        {
            if (current == stage) throw failure;
        }
        Assert.Same(failure, Record.Exception((Action)(() => { _ =
            ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Path, "machine.json",
                json => { Fail("parse"); return JsonSerializer.Deserialize<Document>(json, Options); },
                value => { Fail("schema"); return true; },
                value => { Fail("resolve"); return value; }, CancellationToken.None); })));
    }

    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 0)]
    public async Task JsonPolicyRemainsOwnedByTheParser(bool disallow, int expected)
    {
        using var fixture = new Fixture();
        fixture.Write("a", "{\"schemaVersion\":1,\"name\":\"value\",\"unknown\":1}");
        var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
        {
            UnmappedMemberHandling = disallow ? JsonUnmappedMemberHandling.Disallow : JsonUnmappedMemberHandling.Skip
        };
        var task = ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Path, "machine.json",
            json => JsonSerializer.Deserialize<Document>(json, options),
            static value => value.SchemaVersion == 1, static value => value, CancellationToken.None);
        Assert.Equal(expected, (await task).Count);
    }

    private static string Json(Document value) => JsonSerializer.Serialize(value, Options);

    private sealed record Document(int SchemaVersion, string Name);

    private sealed class Fixture : IDisposable
    {
        private static readonly string Workspace = System.IO.Path.GetFullPath(@"F:\GW GUI");
        public string Path { get; } = System.IO.Path.Combine(Workspace, ".load-audit-" + Guid.NewGuid().ToString("N"));

        public Fixture()
        {
            Validate();
            Directory.CreateDirectory(Path);
        }

        public void Write(string directory, string json)
        {
            var path = System.IO.Path.Combine(Path, directory);
            Directory.CreateDirectory(path);
            File.WriteAllText(System.IO.Path.Combine(path, "machine.json"), json);
        }

        public void Dispose()
        {
            Validate();
            if (Directory.Exists(Path)) Directory.Delete(Path, recursive: true);
        }

        private void Validate()
        {
            var full = System.IO.Path.GetFullPath(Path);
            if (!string.Equals(System.IO.Path.GetDirectoryName(full), Workspace, StringComparison.OrdinalIgnoreCase)
                || !System.IO.Path.GetFileName(full).StartsWith(".load-audit-", StringComparison.Ordinal))
                throw new InvalidOperationException("Fixture must stay in the workspace");
        }
    }
}

